/**
 * Component fingerprints: elements rendered by the same component get the same
 * fingerprint, so 40 identical list items become one issue with 40 instances.
 * Pure string logic, safe to unit-test without a DOM.
 */

/** Class names generated by CSS-in-JS and CSS Modules tooling. */
const GENERATED_CLASS_PATTERNS: readonly RegExp[] = [
  /^css-[a-z0-9]{4,}$/i, // Emotion
  /^sc-[a-z0-9]{4,}$/i, // styled-components
  /^jsx-\d+$/, // styled-jsx
  /^svelte-[a-z0-9]{4,}$/i, // Svelte
  /^ng-(tns|star)-/, // Angular
  /__[a-z0-9]{5,}$/i, // CSS Modules: Button_primary__3xYz1
  /^_[a-z0-9]+_[a-z0-9]{5,}$/i, // CSS Modules: _primary_1x2y3
];

/** Classes describing transient state, not identity. */
const STATE_CLASSES = new Set(['active', 'selected', 'open', 'current', 'focus', 'hover']);
const STATE_PREFIXES = ['is-', 'has-'];

/** True for class names or ids that are generated hashes rather than authored names. */
export function isGeneratedName(name: string): boolean {
  if (GENERATED_CLASS_PATTERNS.some((pattern) => pattern.test(name))) return true;
  // Long runs that mix letters and at least three digits look like hashes.
  const digits = name.replace(/\D/g, '').length;
  return name.length >= 6 && digits >= 3 && /[a-z]/i.test(name) && !/[-_]/.test(name);
}

/** Authored, identity-carrying class names, sorted for a stable signature. */
export function stableClasses(classNames: readonly string[]): string[] {
  const kept = classNames.filter(
    (name) =>
      name.length > 0 &&
      !isGeneratedName(name) &&
      !STATE_CLASSES.has(name) &&
      !STATE_PREFIXES.some((prefix) => name.startsWith(prefix)),
  );
  return [...new Set(kept)].sort();
}

export interface ElementSignatureInput {
  tag: string;
  role: string | null;
  classNames: readonly string[];
}

export function elementSignature({ tag, role, classNames }: ElementSignatureInput): string {
  const classes = stableClasses(classNames);
  return `${tag}${role ? `[role=${role}]` : ''}${classes.length > 0 ? `.${classes.join('.')}` : ''}`;
}
